(function(){(()=>{"use strict";const e=(a,i,r,o,n,s,t)=>({g:a,p:i,n:r,f:o,how:n,ex:s,...t?{fig:t}:{}});window.PhysicaRankDevicesJee={chapter:"Electronic Devices",secs:["Energy bands and types of solids","Intrinsic and extrinsic semiconductors","Carriers, mobility and current","The p-n junction","Diode characteristics and ideal-diode circuits","Rectifiers and the Zener regulator","LED, photodiode and solar cell","Logic gates and Boolean algebra"],table:[["Band gap Eg","ML\xB2T\u207B\xB2 (J or eV)"],["Resistivity \u03C1","ML\xB3T\u207B\xB3A\u207B\xB2 (\u03A9 m)"],["Conductivity \u03C3 = 1/\u03C1","M\u207B\xB9L\u207B\xB3T\xB3A\xB2 (S/m)"],["Carrier concentration n (per volume)","L\u207B\xB3 (m\u207B\xB3)"],["Mobility \u03BC = v/E","M\u207B\xB9T\xB2A (m\xB2/(V s))"],["Current I = e A n v","A (ampere)"],["Barrier potential V\u2080","ML\xB2T\u207B\xB3A\u207B\xB9 (volt)"],["Dynamic resistance r = \u0394V/\u0394I","ML\xB2T\u207B\xB3A\u207B\xB2 (ohm)"],["Frequency of the output f","T\u207B\xB9 (hertz)"],["Ripple factor r","dimensionless"],["Zener voltage Vz","ML\xB2T\u207B\xB3A\u207B\xB9 (volt)"],["Efficiency \u03B7 of a solar cell","dimensionless (a ratio of powers)"]],formulas:[e("Energy bands and types of solids",1,"Conductors, semiconductors and insulators","in a solid the allowed energies form bands: the valence band (VB, filled with the bonding electrons) and the conduction band (CB, free electrons) \xB7 the forbidden gap Eg lies between the top of the VB and the bottom of the CB \xB7 conductor: bands overlap or the CB is partly filled, so Eg = 0 \xB7 semiconductor: Eg < 3 eV (Si 1.1 eV, Ge 0.67 eV) \xB7 insulator: Eg > 3 eV (diamond about 5.4 eV) \xB7 resistivity: conductors \u03C1 < 10\u207B\u2075 \u03A9 m, semiconductors 10\u207B\u2075 to 10\u2076 \u03A9 m, insulators \u03C1 > 10\u2078 \u03A9 m","Look at the gap: none, small or large. At 0 K a pure semiconductor has a full VB and an empty CB, so it behaves as an insulator.","Si has Eg = 1.1 eV and Ge has 0.67 eV, so both are semiconductors; diamond with 5.4 eV is an insulator.","edband"),e("Energy bands and types of solids",1,"Band gap and wavelength of light","a photon can lift an electron across the gap if hf \u2265 Eg \xB7 the longest such wavelength is \u03BBmax = {hc;Eg} = {1240;Eg in eV} nm \xB7 for Si, \u03BBmax = {1240;1.1} = 1127 nm; for Ge, {1240;0.67} = 1851 nm \xB7 light of a longer wavelength is not absorbed in this way \xB7 the same relation gives the colour of the light from an LED, \u03BB = {1240;Eg} nm","Divide 1240 by the gap in eV and you get the wavelength in nm. A larger gap means a shorter wavelength.","Si: \u03BBmax = 1240 \xF7 1.1 = 1127 nm, which is in the infrared. A red LED with Eg = 1.9 eV gives \u03BB = 1240 \xF7 1.9 = 653 nm."),e("Energy bands and types of solids",1,"Effect of temperature on resistance","metal: resistance rises with T (the collisions increase, the number of free electrons stays nearly constant) \xB7 semiconductor: resistance falls with T (more electron\u2013hole pairs are produced, so n rises faster than the collisions) \xB7 temperature coefficient of resistance: positive for metals, negative for semiconductors \xB7 at 0 K a pure semiconductor is an insulator","For a statement about heating, name the carriers: metals keep the same number of carriers and lose speed; semiconductors gain carriers.","Heating a piece of germanium from 300 K to 350 K makes its resistance fall; heating a copper wire makes it rise."),e("Energy bands and types of solids",2,"Pair generation and recombination","heat or light with hf \u2265 Eg lifts an electron from the VB to the CB and leaves a hole in the VB \xB7 this is the creation of an electron\u2013hole pair \xB7 an electron falling back into a hole is recombination \xB7 in steady state the rate of generation equals the rate of recombination \xB7 a hole is a missing electron: it behaves as a particle of charge +e that moves opposite to the electrons","Count pairs: one electron in the CB always means one hole in the VB in a pure crystal.","Light of 600 nm (2.07 eV) on silicon (1.1 eV) makes pairs; light of 1500 nm (0.83 eV) does not."),e("Intrinsic and extrinsic semiconductors",1,"Intrinsic semiconductor","a pure crystal such as Si or Ge (4 valence electrons, covalent bonds) \xB7 n\u2091 = n\u2095 = n\u1D62 \xB7 at 300 K, n\u1D62 \u2248 1.5 \xD7 10\xB9\u2076 m\u207B\xB3 for Si, a very small fraction of the 5 \xD7 10\xB2\u2078 atoms per m\xB3 \xB7 conductivity is small and rises quickly with temperature \xB7 the current is carried by both electrons and holes in equal numbers","Remember n\u2091 = n\u2095 for a pure crystal. Whenever the question says pure or intrinsic, the two concentrations are equal.","In pure Si, n\u2091 = n\u2095 = 1.5 \xD7 10\xB9\u2076 m\u207B\xB3 and so n\u2091n\u2095 = 2.25 \xD7 10\xB3\xB2 m\u207B\u2076."),e("Intrinsic and extrinsic semiconductors",1,"n-type semiconductor","doped with a pentavalent atom (P, As, Sb) which gives one extra electron per atom, called a donor \xB7 the donor level lies just below the CB, so the extra electrons enter the CB easily at room temperature \xB7 majority carriers: electrons; minority carriers: holes \xB7 n\u2091 \u226B n\u2095 and n\u2091 \u2248 N_D (the donor concentration) \xB7 the crystal is still electrically neutral","Pentavalent means n-type. The majority carriers are electrons; the donor atom becomes a fixed positive ion.","Si doped with 5 \xD7 10\xB2\xB2 m\u207B\xB3 of phosphorus: n\u2091 \u2248 5 \xD7 10\xB2\xB2 m\u207B\xB3 and the hole concentration becomes small, about 4.5 \xD7 10\u2079 m\u207B\xB3.","edband"),e("Intrinsic and extrinsic semiconductors",1,"p-type semiconductor","doped with a trivalent atom (B, Al, Ga, In) which has one bond missing, called an acceptor \xB7 the acceptor level lies just above the VB, so electrons from the VB fill it easily and leave holes \xB7 majority carriers: holes; minority carriers: electrons \xB7 n\u2095 \u226B n\u2091 and n\u2095 \u2248 N_A (the acceptor concentration) \xB7 the crystal is still electrically neutral; the acceptor becomes a fixed negative ion","Trivalent means p-type. A hole moves as a positive charge, but the crystal as a whole has no net charge.","Si doped with 2 \xD7 10\xB2\xB2 m\u207B\xB3 of boron: n\u2095 \u2248 2 \xD7 10\xB2\xB2 m\u207B\xB3 and n\u2091 = 2.25 \xD7 10\xB3\xB2 \xF7 2 \xD7 10\xB2\xB2 = 1.1 \xD7 10\xB9\u2070 m\u207B\xB3."),e("Intrinsic and extrinsic semiconductors",2,"What doping does to the energy picture","n-type: a donor level a little below the CB (the gap to the CB is about 0.01 eV to 0.05 eV) \xB7 p-type: an acceptor level a little above the VB \xB7 the doping is small, about 1 atom in 10\u2076 to 10\u2078, yet it raises the conductivity thousands of times \xB7 a doped crystal has more charge carriers than a pure one at the same temperature","Draw the band picture: a donor level just under the CB for n-type, an acceptor level just over the VB for p-type.","Adding one atom of arsenic per 10\u2077 atoms of Si gives about 5 \xD7 10\xB2\xB9 electrons per m\xB3, far more than the intrinsic 1.5 \xD7 10\xB9\u2076.","edband"),e("Intrinsic and extrinsic semiconductors",2,"Compensated and mixed doping","if both donors and acceptors are present, the larger concentration wins \xB7 net n-type if N_D > N_A, with n\u2091 \u2248 N_D \u2212 N_A \xB7 net p-type if N_A > N_D, with n\u2095 \u2248 N_A \u2212 N_D \xB7 charge neutrality: n\u2091 + N_A = n\u2095 + N_D","Subtract the smaller doping from the larger one; the answer is the majority concentration.","N_D = 8 \xD7 10\xB2\xB2 m\u207B\xB3 and N_A = 3 \xD7 10\xB2\xB2 m\u207B\xB3: the crystal is n-type with n\u2091 \u2248 5 \xD7 10\xB2\xB2 m\u207B\xB3."),e("Carriers, mobility and current",1,"Law of mass action","n\u2091 n\u2095 = n\u1D62\xB2 \xB7 this holds in pure and in doped crystals at a given temperature \xB7 doping with donors raises n\u2091 and lowers n\u2095 in exactly the same proportion that makes the product n\u1D62\xB2 \xB7 so the minority concentration is n\u2095 = {n\u1D62\xB2;n\u2091} in an n-type crystal and n\u2091 = {n\u1D62\xB2;n\u2095} in a p-type crystal","Find the majority concentration from the doping, then divide n\u1D62\xB2 by it to get the minority concentration.","Si with n\u1D62 = 1.5 \xD7 10\xB9\u2076 m\u207B\xB3 and n\u2091 = 5 \xD7 10\xB2\xB2 m\u207B\xB3: n\u2095 = 2.25 \xD7 10\xB3\xB2 \xF7 5 \xD7 10\xB2\xB2 = 4.5 \xD7 10\u2079 m\u207B\xB3."),e("Carriers, mobility and current",1,"Current in a semiconductor","I = e A (n\u2091 v\u2091 + n\u2095 v\u2095) = I\u2091 + I\u2095 \xB7 the electron and hole currents add, because the electrons drift one way and the holes the other way, and both give current in the same direction \xB7 for an n-type crystal I\u2091 \u226B I\u2095, so I \u2248 e A n\u2091 v\u2091 \xB7 for a p-type crystal I \u2248 e A n\u2095 v\u2095 \xB7 current density J = e (n\u2091 v\u2091 + n\u2095 v\u2095)","Write the two terms separately, put the same A and e in both, and add. For doped crystals one term is usually negligible.","A = 1 mm\xB2, n\u2091 = 5 \xD7 10\xB2\u2070 m\u207B\xB3, n\u2095 = 4 \xD7 10\xB2\u2070 m\u207B\xB3, v\u2091 = 0.5 m/s, v\u2095 = 0.2 m/s: I = 1.6 \xD7 10\u207B\xB9\u2079 \xD7 10\u207B\u2076 \xD7 (2.5 \xD7 10\xB2\u2070 + 0.8 \xD7 10\xB2\u2070) = 5.28 \xD7 10\u207B\u2075 A = 52.8 \u03BCA."),e("Carriers, mobility and current",1,"Mobility and conductivity","drift speed v = \u03BCE \xB7 \u03C3 = e (n\u2091 \u03BC\u2091 + n\u2095 \u03BC\u2095) and \u03C1 = {1;\u03C3} \xB7 \u03BC in m\xB2/(V s) \xB7 for Si: \u03BC\u2091 = 0.135 and \u03BC\u2095 = 0.048 m\xB2/(V s), so electrons move faster than holes in the same field \xB7 in a doped crystal \u03C3 \u2248 e n\u2091 \u03BC\u2091 (n-type) or e n\u2095 \u03BC\u2095 (p-type)","Use v = \u03BCE to turn a field into a drift speed, then put it in I = eA(n\u2091v\u2091 + n\u2095v\u2095).","Pure Si in E = 200 V/m: v\u2091 = 0.135 \xD7 200 = 27 m/s, v\u2095 = 9.6 m/s. With A = 1 mm\xB2: I = 1.6 \xD7 10\u207B\xB9\u2079 \xD7 10\u207B\u2076 \xD7 1.5 \xD7 10\xB9\u2076 \xD7 (27 + 9.6) = 8.8 \xD7 10\u207B\u2078 A = 88 nA."),e("Carriers, mobility and current",2,"Conductivity of a doped crystal","\u03C3 = e (n\u2091 \u03BC\u2091 + n\u2095 \u03BC\u2095) \xB7 intrinsic: \u03C3 = e n\u1D62 (\u03BC\u2091 + \u03BC\u2095) \xB7 n-type \u03C3 \u2248 e N_D \u03BC\u2091 \xB7 p-type \u03C3 \u2248 e N_A \u03BC\u2095 \xB7 for equal doping n-type conducts better than p-type, because \u03BC\u2091 > \u03BC\u2095","Ignore the minority carriers unless the question asks for them; they are smaller by a factor of about 10\xB9\xB2 here.","Intrinsic crystal with n = 2 \xD7 10\xB9\u2079 m\u207B\xB3, \u03BC\u2091 = 0.39 and \u03BC\u2095 = 0.19 m\xB2/(V s): \u03C3 = 1.6 \xD7 10\u207B\xB9\u2079 \xD7 2 \xD7 10\xB9\u2079 \xD7 0.58 = 1.86 S/m."),e("Carriers, mobility and current",2,"Diffusion current and drift current","drift current: carriers move because of an electric field (I = e A n \u03BC E) \xB7 diffusion current: carriers move from a region of high concentration to low concentration, with no field needed \xB7 in a p-n junction these two currents are in opposite directions and cancel at equilibrium \xB7 diffusion is mostly majority carriers; drift is mostly minority carriers","Name the cause: field gives drift, concentration difference gives diffusion.","At the junction the holes of the p side diffuse into the n side (diffusion), while the field of the depletion layer pushes minority holes back (drift)."),e("The p-n junction",1,"Formation of the depletion layer","electrons diffuse from the n side to the p side, holes from the p side to the n side \xB7 they recombine near the junction \xB7 fixed positive donor ions are left on the n side and fixed negative acceptor ions on the p side \xB7 this region has no mobile carriers: the depletion layer, about 1 \u03BCm thick \xB7 its electric field points from n to p and stops further diffusion \xB7 at equilibrium the diffusion current equals the drift current and the net current is zero","The depletion layer is bare: only fixed ions, no free carriers. Its field always opposes the diffusion of the majority carriers.","A p-n junction in a closed loop with no battery carries no current, because diffusion and drift balance.","edpn"),e("The p-n junction",1,"Barrier potential and the field","the potential difference across the depletion layer is the barrier potential V\u2080: Si about 0.7 V, Ge about 0.3 V \xB7 field E \u2248 {V\u2080;d} across a layer of width d \xB7 the barrier is higher for heavier doping \xB7 V\u2080 cannot be measured by connecting a voltmeter across the diode, since the contact potentials cancel it","Divide the barrier potential by the width to get the field. The potential on the n side is higher than on the p side.","V\u2080 = 0.7 V across d = 1 \u03BCm: E = 0.7 \xF7 10\u207B\u2076 = 7 \xD7 10\u2075 V/m.","edpn"),e("The p-n junction",1,"Forward bias","p side to the positive terminal of the battery, n side to the negative \xB7 the applied voltage opposes the barrier, so the barrier becomes V\u2080 \u2212 V \xB7 the depletion layer becomes thinner \xB7 majority carriers cross the junction, giving a current of the order of mA \xB7 the current rises sharply once V exceeds about 0.7 V (Si) or 0.3 V (Ge) \xB7 the diode conducts and has a small resistance","Check the polarity: p to + is forward. In the forward direction the barrier falls, the layer narrows and the current is large.","A Si diode with 0.5 V forward bias: the barrier is 0.7 \u2212 0.5 = 0.2 V and the current is small; at 0.8 V the current is large.","edpn"),e("The p-n junction",1,"Reverse bias","p side to the negative terminal, n side to the positive \xB7 the applied voltage adds to the barrier, which becomes V\u2080 + V \xB7 the depletion layer becomes wider \xB7 only minority carriers cross, so the reverse current is very small (\u03BCA or nA) and almost independent of V \xB7 the diode does not conduct and has a very large resistance \xB7 at the breakdown voltage the current suddenly becomes large","Reverse bias means a wide depletion layer and a tiny current, even for a large voltage, until breakdown.","A Si diode reverse biased with 5 V: the barrier is 5.7 V and the current is a few \u03BCA at most.","edpn"),e("Diode characteristics and ideal-diode circuits",1,"I\u2013V characteristic","forward: the current is small until the knee voltage (about 0.7 V for Si, 0.3 V for Ge) and then rises steeply (exponentially) \xB7 reverse: a small constant current (\u03BCA) until the breakdown voltage \xB7 the curve is not a straight line: a diode does not obey Ohm\u2019s law \xB7 the characteristic is drawn with the forward current in mA and the reverse current in \u03BCA","On the graph, read the knee on the positive voltage axis and the breakdown on the negative axis. Ge starts to conduct earlier than Si.","On the curve of a Si diode, the current at 0.5 V is almost zero, while at 0.8 V it is many mA.","ediv"),e("Diode characteristics and ideal-diode circuits",1,"Dynamic (a.c.) resistance","r = {\u0394V;\u0394I} at the working point (the slope of the I\u2013V curve is 1/r) \xB7 in the forward region r is small (a few ohms to tens of ohms) \xB7 in the reverse region r is very large (M\u03A9) \xB7 static resistance is V/I at a point and is different from r","Pick two nearby points on the steep part of the curve and divide the change of voltage by the change of current.","The current changes from 10 mA to 20 mA when V changes from 0.70 V to 0.80 V: r = 0.1 \xF7 0.010 = 10 \u03A9.","ediv"),e("Diode characteristics and ideal-diode circuits",2,"Zener breakdown and avalanche breakdown","Zener breakdown: in a heavily doped diode the depletion layer is very thin, so a small reverse voltage (below about 6 V) gives a very strong field that pulls electrons out of the bonds \xB7 avalanche breakdown: in a lightly doped diode, above about 6 V, fast carriers knock out more carriers and the current multiplies \xB7 after breakdown the reverse voltage stays nearly constant while the current changes by a large amount \xB7 this property is used in the Zener diode","Remember the use, not the details: in breakdown the voltage across the Zener is fixed at Vz.","A Zener diode of Vz = 6 V stays at about 6 V while its reverse current changes from 5 mA to 20 mA.","ediv"),e("Diode characteristics and ideal-diode circuits",1,"Ideal diode rules for circuits","forward biased (the anode at a higher potential than the cathode): treat as a short circuit, zero resistance, zero drop \xB7 reverse biased: treat as an open circuit, no current \xB7 for a real silicon diode, the forward drop is 0.7 V (Ge 0.3 V) \xB7 method: assume each diode is on or off, find the current and check that the assumption fits the polarity","Guess the state of each diode, replace it by a wire or a gap, solve, then check the sign of the current and the voltage.","A 5 V battery, a forward ideal diode and 1 k\u03A9: I = 5 \xF7 1000 = 5 mA. With a real Si diode: I = (5 \u2212 0.7) \xF7 1000 = 4.3 mA."),e("Diode characteristics and ideal-diode circuits",1,"Diodes in series and in parallel","a reverse-biased diode in a branch removes that branch: no current flows in it \xB7 two forward diodes in series drop 0.7 V + 0.7 V = 1.4 V (Si) \xB7 two forward Si diodes in parallel share the current and keep the drop at 0.7 V \xB7 a Ge diode (0.3 V) in parallel with a Si diode (0.7 V) conducts first and holds the voltage at 0.3 V, so the Si diode stays off \xB7 the voltage across a conducting real diode is fixed at 0.7 V, whatever the current","Mark the branches that are cut by a reverse diode and then use the series\u2013parallel rules for the rest.","A 10 V battery feeds a 2 k\u03A9 resistor, which divides into two branches, each with a 3 k\u03A9 resistor and an ideal diode, one forward and one reversed. Only one branch conducts: I = 10 \xF7 (2 + 3) k\u03A9 = 2 mA."),e("Diode characteristics and ideal-diode circuits",2,"Voltage drop across a diode in a loop","if the source voltage is below the knee voltage the diode current is nearly zero \xB7 with several sources, the diode conducts only if the anode is at least 0.7 V (real Si) above the cathode \xB7 the potential of the point between a resistor and a conducting diode is clamped by the diode \xB7 in a clipping circuit the output follows the input only up to the diode voltage","To find the output of a clipper, compare the input with the diode voltage in each half cycle.","A Si diode in parallel with the output (series resistor) clips the positive peaks at +0.7 V: a 5 V peak input gives a +0.7 V peak at the output."),e("Rectifiers and the Zener regulator",1,"Half-wave rectifier","one diode in series with the load \xB7 conducts in the positive half cycles only \xB7 output is a series of positive pulses with the same frequency as the input: f_out = f_in \xB7 for 50 Hz mains, the output is 50 Hz \xB7 Vdc = {Vm;\u03C0} = 0.318 Vm and Vrms = {Vm;2} \xB7 ripple factor r = 1.21 \xB7 efficiency about 40 %","Count the humps per input cycle: one hump per cycle gives the same frequency as the input.","Vm = 10 V: Vdc = 10 \xF7 \u03C0 = 3.18 V and Vrms = 5 V. A 50 Hz supply gives 50 Hz pulses.","edhw"),e("Rectifiers and the Zener regulator",1,"Full-wave rectifier","two diodes with a centre-tapped transformer (or four diodes in a bridge) \xB7 each half cycle one diode conducts, so the current in the load always has one direction \xB7 f_out = 2 f_in \xB7 for 50 Hz mains, the output is 100 Hz \xB7 Vdc = {2Vm;\u03C0} = 0.637 Vm and Vrms = {Vm;\u221A(2)} \xB7 ripple factor r = 0.48 \xB7 efficiency about 81 %","The full-wave circuit has twice as many humps. The dc value is double the half-wave value.","Vm = 10 V: Vdc = 20 \xF7 \u03C0 = 6.37 V and Vrms = 10 \xF7 \u221A2 = 7.07 V. A 50 Hz supply gives 100 Hz output.","edfw"),e("Rectifiers and the Zener regulator",2,"Bridge rectifier and peak inverse voltage","bridge: four diodes, two conduct in each half cycle, so the peak output is Vm \u2212 2 \xD7 0.7 V for Si \xB7 centre-tap: one diode conducts, the output peak is Vm of half the winding minus 0.7 V \xB7 peak inverse voltage (PIV): half-wave Vm, centre-tap full-wave 2Vm, bridge Vm \xB7 the diode must have a reverse breakdown voltage larger than the PIV","For a real diode subtract 0.7 V once per diode in the path of the current, and for the PIV remember the factor 2 only for the centre-tapped circuit.","A transformer secondary of 12 V rms has Vm = 12\u221A2 = 16.97 V. A half-wave Si circuit gives a peak output of 16.97 \u2212 0.7 = 16.3 V; a bridge gives 16.97 \u2212 1.4 = 15.6 V.","edfw"),e("Rectifiers and the Zener regulator",2,"Filter capacitor and ripple","a capacitor across the load charges to the peak and discharges slowly through R between the peaks \xB7 the ripple (peak to peak) \u0394V \u2248 {I;f_out C} = {I T_out;C} \xB7 a large C and a large f_out reduce the ripple \xB7 ripple factor r = {V_ac (rms);V_dc} \xB7 the full-wave circuit needs a smaller C than the half-wave circuit for the same ripple","The capacitor loses charge \u0394Q = I \xD7 T between the peaks, so \u0394V = \u0394Q/C.","Full-wave output of 100 Hz, I = 20 mA and C = 1000 \u03BCF: \u0394V = 0.020 \xF7 (100 \xD7 10\u207B\xB3) = 0.2 V."),e("Rectifiers and the Zener regulator",1,"Zener diode as a voltage regulator","the Zener diode is connected in reverse bias across the load, with a series resistor Rs \xB7 in breakdown, Vout = Vz is nearly constant \xB7 I = {V_in \u2212 Vz;Rs} and I_L = {Vz;R_L} and I = Iz + I_L \xB7 power in the Zener Pz = Vz Iz \xB7 if V_in rises, I and Iz rise and Vout stays at Vz; if the load current rises, Iz falls","Find I in Rs first, then I_L from the load, and subtract to get Iz. The Zener takes what the load does not.","V_in = 15 V, Vz = 10 V, Rs = 500 \u03A9, R_L = 2 k\u03A9: I = 5 \xF7 500 = 10 mA, I_L = 10 \xF7 2000 = 5 mA, Iz = 5 mA and Pz = 10 \xD7 5 mA = 50 mW.","edzen"),e("Rectifiers and the Zener regulator",1,"Limits of the Zener regulator","the regulator works only while Iz stays between a minimum (about 1 mA, the breakdown is lost below this) and a maximum (set by the power rating) \xB7 greatest load current: when Iz is at its minimum, I_L(max) = I \u2212 Iz(min) \xB7 greatest Iz: no load or smallest load and the highest V_in, Iz(max) = {V_in(max) \u2212 Vz;Rs} \xB7 if R_L is open, Iz = I \xB7 if V_in < Vz the Zener does not break down and Vout = V_in \xD7 {R_L;Rs + R_L}","Decide which end you test: lowest V_in with the largest load gives the smallest Iz; highest V_in with no load gives the largest Iz.","With V_in = 15 V, Vz = 10 V, Rs = 500 \u03A9 and Iz(min) = 1 mA: I = 10 mA, I_L(max) = 9 mA and R_L(min) = 10 \xF7 0.009 = 1111 \u03A9. With the load open and V_in = 20 V, Iz = 10 \xF7 500 = 20 mA and Pz = 0.2 W.","edzen"),e("LED, photodiode and solar cell",1,"Light-emitting diode (LED)","a p-n junction of a compound such as GaAs, GaAsP or GaP, operated in forward bias \xB7 electrons and holes recombine and the energy released leaves as a photon of hf \u2248 Eg \xB7 colour of light \u03BB = {1240;Eg in eV} nm \xB7 typical forward voltage 1.5 V to 3 V \xB7 the series resistor is R = {V \u2212 V_LED;I} \xB7 a larger Eg gives a shorter wavelength (green and blue need more than red) \xB7 it does not produce light in reverse bias","LED means forward bias and light out. Do not use silicon, because its gap is indirect and the emission is weak.","Eg = 1.9 eV: \u03BB = 1240 \xF7 1.9 = 653 nm, red. On 5 V with 2 V across the LED and 20 mA: R = (5 \u2212 2) \xF7 0.020 = 150 \u03A9."),e("LED, photodiode and solar cell",1,"Photodiode","a p-n junction used in reverse bias, with a window for light \xB7 photons with hf \u2265 Eg make electron\u2013hole pairs in the depletion region \xB7 the field sweeps them across, so the reverse current rises with the light intensity \xB7 the current without light is the small dark current \xB7 it is used to detect light signals and to count photons \xB7 I_photo \u221D intensity (the number of photons per second)","Reverse bias plus light gives a larger reverse current. The change in current measures the intensity.","1 \u03BCW of 620 nm light: N = 10\u207B\u2076 \xD7 620 \xD7 10\u207B\u2079 \xF7 1.99 \xD7 10\u207B\xB2\u2075 = 3.1 \xD7 10\xB9\xB2 photons per second. If every photon makes one pair, I = 3.1 \xD7 10\xB9\xB2 \xD7 1.6 \xD7 10\u207B\xB9\u2079 = 0.5 \u03BCA."),e("LED, photodiode and solar cell",1,"Solar cell","a p-n junction with a large area, no external bias \xB7 photons with hf \u2265 Eg make pairs near the junction and the field separates them, giving an emf \xB7 open-circuit voltage Voc about 0.5 V to 0.6 V for Si; short-circuit current Isc \xB7 the I\u2013V curve lies in the fourth quadrant \xB7 maximum power Pm = FF \xD7 Voc \xD7 Isc (FF the fill factor, less than 1) \xB7 efficiency \u03B7 = {Pm;P_in} with P_in = (intensity) \xD7 (area)","A solar cell is a source, not a load: its curve is in the fourth quadrant. Efficiency is the electrical power divided by the light power received.","Voc = 0.6 V, Isc = 3.0 A, FF = 0.75: Pm = 0.75 \xD7 0.6 \xD7 3.0 = 1.35 W. On 10 W of light, \u03B7 = 1.35 \xF7 10 = 13.5 %."),e("LED, photodiode and solar cell",2,"Comparing the three optical diodes","LED: forward bias, converts electric energy to light \xB7 photodiode: reverse bias, converts light to a current signal that depends on intensity \xB7 solar cell: no bias, converts light to electric power \xB7 in all three the photon energy is near the band gap \xB7 the LED and the laser diode need a direct-gap material","Match the bias: forward for LED, reverse for photodiode, none for solar cell.","A remote control uses an infrared LED (forward bias) and a photodiode (reverse bias) in the receiver."),e("Logic gates and Boolean algebra",1,"OR, AND and NOT gates","OR: Y = A + B; output 1 if at least one input is 1 \xB7 AND: Y = A\xB7B; output 1 only if both inputs are 1 \xB7 NOT: Y = A\u0305; the output is the opposite of the input \xB7 outputs for AB = 00, 01, 10, 11: OR 0, 1, 1, 1; AND 0, 0, 0, 1 \xB7 NOT: A = 0 gives 1, A = 1 gives 0 \xB7 switch picture: OR is two switches in parallel, AND is two switches in series","Learn the three tables as sentences: OR is any one, AND is all, NOT is the opposite.","Inputs A = 1 and B = 0: OR gives 1, AND gives 0, NOT A gives 0.","edgate"),e("Logic gates and Boolean algebra",1,"NAND and NOR gates","NAND: Y = NOT(A\xB7B) = A\u0305 + B\u0305; AND followed by NOT \xB7 NOR: Y = NOT(A + B) = A\u0305\xB7B\u0305; OR followed by NOT \xB7 outputs for AB = 00, 01, 10, 11: NAND 1, 1, 1, 0; NOR 1, 0, 0, 0 \xB7 NAND is 0 only when both inputs are 1; NOR is 1 only when both inputs are 0","For NAND write the AND table and then flip every output. For NOR write the OR table and flip every output.","Inputs A = 1 and B = 1: NAND gives 0 and NOR gives 0. Inputs 0 and 0: NAND gives 1 and NOR gives 1.","edgate"),e("Logic gates and Boolean algebra",1,"Universal gates","any logic function can be made from NAND gates alone, or from NOR gates alone \xB7 NAND: NOT = both inputs joined, Y = NOT(A\xB7A) = A\u0305 \xB7 NAND: AND = a NAND followed by a NAND used as NOT (2 gates) \xB7 NAND: OR = a NAND used as NOT on each input, then a NAND (3 gates), because NOT(A\u0305\xB7B\u0305) = A + B \xB7 NOR: NOT = both inputs joined \xB7 NOR: OR = a NOR followed by a NOR as NOT (2 gates) \xB7 NOR: AND = a NOR used as NOT on each input, then a NOR (3 gates), because NOT(A\u0305 + B\u0305) = A\xB7B","Use the two moves: join the inputs to make a NOT, and put a NOT before or after to change the gate. Count the gates.","To make an OR from NAND gates: A and B each go into a NAND with both inputs joined (giving A\u0305 and B\u0305), then both go into a third NAND: Y = NOT(A\u0305\xB7B\u0305) = A + B.","edgate"),e("Logic gates and Boolean algebra",1,"Boolean identities and De Morgan\u2019s laws","A + 0 = A \xB7 A + 1 = 1 \xB7 A\xB70 = 0 \xB7 A\xB71 = A \xB7 A + A = A \xB7 A\xB7A = A \xB7 A + A\u0305 = 1 \xB7 A\xB7A\u0305 = 0 \xB7 NOT(A\u0305) = A \xB7 De Morgan: NOT(A + B) = A\u0305\xB7B\u0305 and NOT(A\xB7B) = A\u0305 + B\u0305 \xB7 absorption: A + A\xB7B = A and A\xB7(A + B) = A \xB7 A + A\u0305\xB7B = A + B","Use De Morgan to push a bar into brackets: change the sign (+ to \xB7, or the other way) and put a bar on each letter.","NOT(A + B) + A\xB7B: for A = 1, B = 1 this is 0 + 1 = 1; for A = 1, B = 0 it is 0 + 0 = 0."),e("Logic gates and Boolean algebra",1,"Output of a gate network","work step by step from the inputs to the output, writing the output of every gate \xB7 NOT on both inputs of an AND gives NOR: A\u0305\xB7B\u0305 \xB7 NOT on both inputs of an OR gives NAND: A\u0305 + B\u0305 \xB7 AND followed by NOT gives NAND; OR followed by NOT gives NOR \xB7 OR of A\xB7B\u0305 and A\u0305\xB7B gives the XOR output (0, 1, 1, 0 for AB = 00, 01, 10, 11)","Write the output of every gate on the diagram, in the order of the signal. Check with all four input pairs.","Y = (A + B)\xB7NOT(A\xB7B): for AB = 00, 01, 10, 11 it gives 0, 1, 1, 0, which is the XOR output."),e("Logic gates and Boolean algebra",2,"Simplifying a Boolean expression","use the identities to cut the number of gates \xB7 A + A\u0305\xB7B = A + B \xB7 A\xB7B + A\xB7B\u0305 = A \xB7 A\xB7(A\u0305 + B) = A\xB7B \xB7 (A + B)\xB7(A + B\u0305) = A \xB7 a quick check: make the truth table of both sides and compare","Try an identity first; if you are unsure, test all four input pairs.","Y = A + A\u0305\xB7B: for AB = 00, 01, 10, 11, A + A\u0305B = 0, 1, 1, 1, which is the same as A + B."),e("Logic gates and Boolean algebra",2,"Gates made with diodes and resistors","OR gate: two diodes with the anodes at the inputs and the cathodes joined to a resistor to ground \xB7 output high if any input is high (about V \u2212 0.7 V for a real diode) \xB7 AND gate: two diodes with the cathodes at the inputs and the anodes joined to a resistor to +V \xB7 output low if any input is low \xB7 NOT gate: needs a transistor (an amplifying device); a diode alone cannot invert","In the diode OR gate the highest input drives the output; in the diode AND gate the lowest input holds the output down.","In the diode AND gate with inputs 5 V and 0 V, the diode at the 0 V input conducts and the output is about 0.7 V, a logic 0."),e("Logic gates and Boolean algebra",2,"Input and output waveforms","draw the inputs in time slots of equal width and apply the truth table in each slot \xB7 A = 1, 1, 0, 0 and B = 1, 0, 1, 0 in four slots: AND 1, 0, 0, 0 \xB7 OR 1, 1, 1, 0 \xB7 NAND 0, 1, 1, 1 \xB7 NOR 0, 0, 0, 1 \xB7 a change at the input shows at the output with no change of the shape","Divide the time axis by every change of A or B, then read the output slot by slot.","A = 1100 and B = 1010 into an OR gate give Y = 1110, and into a NOR gate Y = 0001.")],look:["Conductor: bands overlap; semiconductor: Eg < 3 eV (Si 1.1, Ge 0.67); insulator: Eg > 3 eV; \u03BB = 1240/Eg nm","Pentavalent (P, As) gives n-type, electrons are the majority; trivalent (B, Al) gives p-type, holes are the majority; the crystal stays neutral","n\u2091 n\u2095 = n\u1D62\xB2; I = e A (n\u2091 v\u2091 + n\u2095 v\u2095); v = \u03BCE; \u03C3 = e (n\u2091 \u03BC\u2091 + n\u2095 \u03BC\u2095)","Junction: depletion layer, barrier V\u2080 (Si 0.7 V, Ge 0.3 V), field from n to p; forward bias narrows it, reverse bias widens it","I\u2013V curve: forward knee at 0.7 V (Si), reverse leakage in \u03BCA, then breakdown; r = \u0394V/\u0394I","Ideal diode: forward is a wire, reverse is a gap; a real Si diode drops 0.7 V; a reverse diode cuts its branch","Half-wave: f_out = f, Vdc = Vm/\u03C0; full-wave: f_out = 2f, Vdc = 2Vm/\u03C0; PIV: Vm (half, bridge), 2Vm (centre-tap)","Zener regulator: reverse biased, Vout = Vz, I = (V \u2212 Vz)/Rs = Iz + I_L; Iz is least at the lowest V and the largest load","LED forward, \u03BB = 1240/Eg; photodiode reverse, current \u221D light; solar cell unbiased, fourth quadrant, \u03B7 = Pm/Pin","OR any, AND all, NOT opposite; NAND/NOR flip AND/OR; De Morgan: NOT(A + B) = A\u0305B\u0305; NAND and NOR are universal"],notes:[{h:"Energy bands and types of solids",items:["In a solid the energy levels of the atoms merge into bands: the valence band (VB) and the conduction band (CB).","Conductor: the bands overlap or the CB is partly filled, so there is no gap.","Semiconductor: a small gap, less than 3 eV (Si 1.1 eV, Ge 0.67 eV).","Insulator: a large gap, more than 3 eV, so almost no electron can reach the CB at room temperature.","The wavelength that corresponds to a gap is \u03BB = 1240/Eg nm.","The resistance of a semiconductor falls when it is heated, the opposite of a metal."],fig:"edband"},{h:"Intrinsic and extrinsic semiconductors",items:["A pure crystal has n\u2091 = n\u2095 = n\u1D62; for Si at 300 K it is 1.5 \xD7 10\xB9\u2076 m\u207B\xB3.","Doping with a pentavalent atom gives an n-type crystal; the electrons are the majority carriers.","Doping with a trivalent atom gives a p-type crystal; the holes are the majority carriers.","The donor level lies just below the CB and the acceptor level just above the VB.","Both n-type and p-type crystals are electrically neutral as a whole.","A very small amount of doping raises the conductivity by a large factor."]},{h:"Carriers, mobility and current",items:["Law of mass action: n\u2091 n\u2095 = n\u1D62\xB2 for any one crystal at a fixed temperature.","Adding donors raises n\u2091 and lowers n\u2095; the product does not change.","The current is I = e A (n\u2091 v\u2091 + n\u2095 v\u2095): the two parts add.","Drift speed is v = \u03BCE, and electrons have a larger mobility than holes.","Conductivity is \u03C3 = e (n\u2091 \u03BC\u2091 + n\u2095 \u03BC\u2095).","A hole is a missing electron; it moves as a positive charge in the direction of the field."]},{h:"The p-n junction",items:["At the junction, electrons diffuse to the p side and holes to the n side and recombine.","This leaves fixed ions: positive on the n side, negative on the p side, a layer without free carriers.","The layer is about 1 \u03BCm thick; the barrier potential is 0.7 V for Si and 0.3 V for Ge.","The field in the depletion layer points from the n side to the p side.","In equilibrium the diffusion current and the drift current cancel and the net current is zero.","The barrier potential cannot be measured with a voltmeter and it does not drive a current by itself."],fig:"edpn"},{h:"Bias, I\u2013V curve and diode circuits",items:["Forward bias (p to +): the barrier falls, the layer is thin, the majority carriers cross and the current is in mA.","Reverse bias (p to \u2212): the barrier rises, the layer is wide, only minority carriers move and the current is in \u03BCA.","At the breakdown voltage the reverse current rises very sharply; a diode does not obey Ohm\u2019s law.","Treat a forward ideal diode as a wire and a reverse one as an open gap; a real Si diode that conducts drops 0.7 V (Ge 0.3 V).","A reverse-biased diode cuts its branch out of the circuit; two forward Si diodes in series drop 1.4 V.","Assume the state of each diode, solve, then confirm that the currents and polarities fit the assumption."],fig:"ediv"},{h:"Rectifiers",items:["A half-wave rectifier uses one diode and gives one pulse per input cycle, so f_out = f.","A full-wave rectifier gives two pulses per cycle, so f_out = 2f (100 Hz for 50 Hz mains).","Vdc = Vm/\u03C0 for half-wave and 2Vm/\u03C0 for full-wave.","A bridge uses four diodes; two conduct together in each half cycle.","A capacitor across the load smooths the output; the ripple is \u0394V = I/(f_out C).","The peak inverse voltage is Vm in the half-wave and bridge circuits and 2Vm for the centre-tap circuit."],fig:"edhw"},{h:"Zener diode as a regulator",items:["The Zener diode is operated in reverse bias in its breakdown region.","In breakdown the voltage across it is nearly constant at Vz, while its current can change a lot.","The series resistor Rs limits the current: I = (V \u2212 Vz)/Rs.","The current splits: I = Iz + I_L, with I_L = Vz/R_L.","If the input rises, Iz rises; if the load current rises, Iz falls; the output stays at Vz.","The regulator works only when Iz stays between its minimum value and its power limit."],fig:"edzen"},{h:"LED, photodiode and solar cell",items:["An LED works in forward bias and gives out light of energy near Eg when electrons and holes recombine.","A photodiode works in reverse bias; light makes pairs and raises the reverse current.","A solar cell has no external bias and delivers power to a load; its curve is in the fourth quadrant.","All three need hf \u2265 Eg for the absorption of light.","A series resistor R = (V \u2212 V_LED)/I protects an LED.","Efficiency of a solar cell is the electric power output divided by the light power received."]},{h:"Logic gates",items:["OR is 1 if any input is 1; AND is 1 only if all inputs are 1; NOT reverses the input.","NAND is AND followed by NOT; NOR is OR followed by NOT.","Truth tables for AB = 00, 01, 10, 11: AND 0001, OR 0111, NAND 1110, NOR 1000.","NAND and NOR are universal gates: any gate can be built from either one.","De Morgan: NOT(A + B) = A\u0305\xB7B\u0305 and NOT(A\xB7B) = A\u0305 + B\u0305.","To find a network output, write the output of each gate step by step and test all input pairs."],fig:"edgate"},{h:"After this chapter: the transistor",items:["A transistor has three layers and two p-n junctions: emitter, base and collector (n-p-n or p-n-p).","The base is thin and lightly doped; the emitter is heavily doped.","The currents obey I_E = I_B + I_C, and the current gain is \u03B2 = I_C/I_B.","It is used as an amplifier and as a switch (and, with it, the NOT gate is built).","Transistors are not in the current JEE Main syllabus: do not spend time on them.","In the common-emitter amplifier the output voltage is inverted (180\xB0 out of phase) compared with the input."]}],asked:[{t:"Classify a solid from its band gap or resistivity",what:"The gap or the resistivity of a material is given. Say whether it is a conductor, a semiconductor or an insulator.",steps:["Eg = 0 (overlap) is a conductor.","0 < Eg < 3 eV is a semiconductor.","Eg > 3 eV is an insulator."],ex:"Eg = 1.1 eV: semiconductor (Si).",tp:"band",fig:"edband"},{t:"Wavelength for a band gap",what:"The band gap is given. Find the longest wavelength that makes electron\u2013hole pairs, or the colour of an LED.",steps:["\u03BB = 1240 \xF7 Eg in nm.","Longer wavelengths do not excite the crystal.","A larger gap gives a shorter wavelength."],ex:"Si, 1.1 eV: 1127 nm.",tp:"band"},{t:"n-type or p-type from the dopant",what:"The dopant is given (P, As, B, Al...). Name the type, the majority and minority carriers and the position of the impurity level.",steps:["Pentavalent: n-type, donor level below the CB.","Trivalent: p-type, acceptor level above the VB.","The crystal stays neutral."],ex:"Boron in Si: p-type, holes are the majority.",tp:"band",fig:"edband"},{t:"Minority concentration from n\u2091 n\u2095 = n\u1D62\xB2",what:"The doping or the majority concentration and n\u1D62 are given. Find the minority concentration.",steps:["Majority \u2248 doping concentration.","n\u2095 = n\u1D62\xB2 \xF7 n\u2091.","Check that the product equals n\u1D62\xB2."],ex:"n\u2091 = 5 \xD7 10\xB2\xB2 m\u207B\xB3: n\u2095 = 4.5 \xD7 10\u2079 m\u207B\xB3.",tp:"band"},{t:"Current from the carrier concentrations and drift speeds",what:"n\u2091, n\u2095, the speeds (or \u03BC and E) and the area are given. Find the current.",steps:["v = \u03BCE if needed.","I = eA (n\u2091 v\u2091 + n\u2095 v\u2095).","Add the electron and hole parts."],ex:"1 mm\xB2, 5 \xD7 10\xB2\u2070 and 4 \xD7 10\xB2\u2070: 52.8 \u03BCA.",tp:"band"},{t:"Depletion layer, barrier and bias",what:"A statement or a diagram about the p-n junction is given. Say how the width of the layer, the barrier and the current change with the bias.",steps:["Forward: barrier V\u2080 \u2212 V, layer narrower.","Reverse: barrier V\u2080 + V, layer wider.","The current is large in forward bias and tiny in reverse bias."],ex:"Forward bias of 0.5 V on Si: barrier 0.2 V.",tp:"diode",fig:"edpn"},{t:"Reading the I\u2013V characteristic",what:"The graph of a diode is given. Find the knee voltage, the breakdown voltage or the dynamic resistance.",steps:["The knee is the forward voltage where the current rises.","r = \u0394V \xF7 \u0394I on the steep part.","The reverse current is in \u03BCA until breakdown."],ex:"10 mA to 20 mA over 0.1 V: 10 \u03A9.",tp:"diode",fig:"ediv"},{t:"Current in a circuit with ideal diodes",what:"A battery, resistors and one or more ideal diodes are given. Find the current or the potential at a point.",steps:["Decide forward or reverse for each diode.","Replace by a wire or a gap.","Solve and check."],ex:"10 V, 2 k\u03A9 and 3 k\u03A9 with one branch cut: 2 mA.",tp:"diode"},{t:"Circuits with real silicon or germanium diodes",what:"A circuit has diodes with drops of 0.7 V (Si) or 0.3 V (Ge). Find the current or the voltage across a resistor.",steps:["Subtract the drop of each conducting diode.","Divide the rest by R.","Diodes in parallel keep the same drop."],ex:"5 V, Si diode, 1 k\u03A9: 4.3 mA.",tp:"diode"},{t:"Output frequency of a rectifier",what:"The input frequency and the type of rectifier are given. Find the frequency of the output pulses.",steps:["Half-wave: f_out = f.","Full-wave (or bridge): f_out = 2f.","Count the humps per cycle."],ex:"50 Hz mains: 50 Hz or 100 Hz.",tp:"rect",fig:"edfw"},{t:"Average and rms output of a rectifier",what:"The peak voltage of the input is given. Find the dc value, the rms value or the ripple factor.",steps:["Half-wave: Vdc = Vm/\u03C0, Vrms = Vm/2.","Full-wave: Vdc = 2Vm/\u03C0, Vrms = Vm/\u221A2.","Subtract 0.7 V per conducting Si diode for a real circuit."],ex:"Vm = 10 V: 3.18 V and 6.37 V.",tp:"rect",fig:"edhw"},{t:"Rectifier waveform and which diode conducts",what:"A circuit with one or two diodes and an a.c. input is given. Draw the output or say which diode conducts in a half cycle.",steps:["A diode conducts when its anode is positive.","Take each half cycle separately.","Reverse the negative half for the full-wave circuit."],ex:"Centre-tap circuit: D1 in the positive, D2 in the negative half cycle.",tp:"rect",fig:"edfw"},{t:"Ripple with a filter capacitor",what:"The load current, the output frequency and the capacitor are given. Find the ripple voltage.",steps:["f_out = f or 2f.","\u0394V = I \xF7 (f_out C).","A larger C or f_out gives a smaller ripple."],ex:"20 mA, 100 Hz, 1000 \u03BCF: 0.2 V.",tp:"rect"},{t:"Zener regulator: the currents",what:"V_in, Vz, Rs and R_L are given. Find the current in Rs, the load current and the Zener current.",steps:["I = (V_in \u2212 Vz) \xF7 Rs.","I_L = Vz \xF7 R_L.","Iz = I \u2212 I_L."],ex:"15 V, 10 V, 500 \u03A9, 2 k\u03A9: 10, 5 and 5 mA.",tp:"rect",fig:"edzen"},{t:"Zener regulator: limits of load and input",what:"The range of the input voltage or the load is given. Find the smallest load resistance, the largest Zener current or the power in the Zener.",steps:["Iz is least for the lowest V_in and the heaviest load.","Iz is greatest for the highest V_in and no load.","P = Vz Iz."],ex:"Load open, 20 V: Iz = 20 mA and P = 0.2 W.",tp:"rect",fig:"edzen"},{t:"LED, photodiode and solar cell: bias and colour",what:"The device and its bias or its gap are given. Name the bias, the energy conversion or the wavelength.",steps:["LED: forward bias, light out, \u03BB = 1240/Eg.","Photodiode: reverse bias, current \u221D light.","Solar cell: no bias, fourth quadrant, light to power."],ex:"Eg = 1.9 eV: 653 nm, red.",tp:"rect"},{t:"Solar cell power and efficiency",what:"Voc, Isc, the fill factor, the area and the light intensity are given. Find the maximum power or the efficiency.",steps:["Pm = FF \xD7 Voc \xD7 Isc.","P_in = intensity \xD7 area.","\u03B7 = Pm \xF7 P_in."],ex:"0.6 V, 3 A, FF 0.75, 10 W of light: 13.5 %.",tp:"rect"},{t:"Truth table of a single gate",what:"A gate is named or its symbol is drawn. Give its output for the input pairs, or identify the gate from its table.",steps:["AND 0001, OR 0111 for AB = 00, 01, 10, 11.","NAND 1110, NOR 1000.","NOT reverses the input."],ex:"Table 1, 1, 1, 0: NAND.",tp:"logic",fig:"edgate"},{t:"Output of a combination of gates",what:"A network of gates is drawn. Find the output Y for given inputs or the equivalent single gate.",steps:["Write the output of each gate in order.","Check all four input pairs.","Name the gate that has the same table."],ex:"NOT on both inputs of an AND is a NOR.",tp:"logic"},{t:"NAND or NOR as a universal gate",what:"A gate (NOT, AND, OR) is to be made from NAND gates alone or NOR gates alone. Give the connection or the number of gates.",steps:["Join the inputs of a NAND or NOR to get NOT.","AND from NAND: 2 gates; OR from NAND: 3 gates.","OR from NOR: 2 gates; AND from NOR: 3 gates."],ex:"OR from NAND: A\u0305 and B\u0305 into a third NAND.",tp:"logic",fig:"edgate"},{t:"Boolean simplification and De Morgan",what:"A Boolean expression is given. Simplify it or find the equivalent gate.",steps:["Use A + A\u0305B = A + B and absorption.","De Morgan: NOT(A + B) = A\u0305B\u0305.","Test with a truth table."],ex:"A + A\u0305B = A + B.",tp:"logic"},{t:"Input and output waveforms of a gate",what:"Two input waveforms are shown for a gate. Draw or choose the output.",steps:["Split the time axis at every edge.","Use the truth table in each slot.","Join the slots."],ex:"A = 1100, B = 1010 into NOR: 0001.",tp:"logic"}],guide:{intro:"Electronic Devices gives 2 or 3 questions in JEE Mains nearly every year, and most of them are quick. You are asked to classify a solid, find the output of a logic network, say what a rectifier does to the frequency, find the current in a diode circuit, or calculate a Zener current. The chapter is mostly facts and short calculations. About 6 hours over 4 days is enough, and logic gates are the easiest marks.",plan:[["Day 1 \xB7 75 min","Energy bands, intrinsic and extrinsic semiconductors, n\u2091 n\u2095 = n\u1D62\xB2, current and mobility."],["Day 2 \xB7 90 min","p-n junction, depletion layer, forward and reverse bias, I\u2013V curve, ideal-diode circuits."],["Day 3 \xB7 90 min","Half-wave and full-wave rectifiers, the Zener regulator, LED, photodiode and solar cell."],["Day 4 \xB7 75 min","Logic gates, truth tables, NAND and NOR as universal gates, Boolean simplification; then the Most asked types and a mock test."]],basics:["Electric current, Ohm\u2019s law and resistors in series and in parallel.","Potential difference and the energy of an electron in eV.","Alternating voltage, peak value, rms value and frequency.","Wavelength, frequency and energy of a photon, E = 1240/\u03BB.","Atomic structure and valence electrons.","Basic ideas of the periodic table (groups 3, 4 and 5)."],path:[{t:"Step 1 \xB7 Bands and semiconductors (Day 1)",d:"Learn the band pictures, the types of doping, the law of mass action and the current formula.",ready:"you can name the type of a doped crystal and find the minority concentration without a hint.",go:"formulas"},{t:"Step 2 \xB7 The junction (Day 2)",d:"Learn the depletion layer, the barrier potential and the effect of forward and reverse bias on the layer and the current.",ready:"you can say what happens to the layer and the current for each bias.",go:"notes"},{t:"Step 3 \xB7 Diode circuits (Day 2)",d:"Practise circuits with ideal and real diodes, deciding on or off for each diode first.",ready:"you solve a three-branch circuit with two diodes in under two minutes.",go:"asked"},{t:"Step 4 \xB7 Rectifiers and Zener (Day 3)",d:"Learn the output frequencies, the dc values, the ripple and the Zener currents with their limits.",ready:"you can find Iz, I_L and the smallest load resistance of a regulator.",go:"formulas"},{t:"Step 5 \xB7 Logic gates (Day 4)",d:"Learn the five truth tables, the universal gates, De Morgan\u2019s laws and how to read a network.",ready:"you can write the output of a four-gate network for all inputs in a minute.",go:"asked"},{t:"Step 6 \xB7 Practise, then test",d:"Practise by question type, then take the mock test.",ready:"you score 8 out of 10 in practice twice in a row.",go:"practice"}],think:["What is the topic: bands, doping, the junction, a diode circuit, a rectifier, the Zener, an optical diode or a logic network?","Is the diode forward or reverse biased? Which side is at the higher potential?","Is the diode ideal (zero drop) or real (0.7 V for Si, 0.3 V for Ge)?","For a rectifier, count the pulses per input cycle to get the output frequency.","For a Zener circuit, find I in Rs first, then I_L, then Iz.","For a gate network, write the output of each gate in order and test all four input pairs.","Check the units: eV with 1240/\u03BB in nm, \u03BCm in m for the field, mA in A for the resistor."],watch:["Forward bias is p to the positive terminal; many students reverse it.","A reverse-biased diode does not conduct; do not put a 0.7 V drop on it.","The output frequency of the full-wave rectifier is 2f, not f.","Vdc is not Vrms: Vdc = Vm/\u03C0 (half-wave) and 2Vm/\u03C0 (full-wave).","The Zener is connected in reverse bias; the series resistor is always needed.","In n\u2091 n\u2095 = n\u1D62\xB2, the minority concentration falls when the majority rises.","NAND is not the same as NOT-A AND NOT-B: that is NOR. NAND is A\u0305 + B\u0305.","An LED needs forward bias and a photodiode needs reverse bias."],myths:[["Myth: An n-type crystal is negatively charged because it has extra electrons.","Truth: Each extra electron comes from a neutral donor atom, which becomes a fixed positive ion. The crystal is neutral."],["Myth: A p-type crystal has holes, so it is positively charged.","Truth: Each hole comes with a negative acceptor ion. The crystal as a whole is neutral."],["Myth: A diode obeys Ohm\u2019s law like a resistor.","Truth: Its I\u2013V curve is not a straight line. The current is almost zero below the knee and rises steeply after it."],["Myth: No current flows in a reverse-biased diode at all.","Truth: A very small leakage current (\u03BCA) flows, carried by the minority carriers, until the breakdown."],["Myth: A rectifier makes the output a perfectly steady dc voltage.","Truth: It makes a pulsating dc. A filter capacitor is needed to smooth it."],["Myth: A full-wave rectifier has the same output frequency as a half-wave rectifier.","Truth: The full-wave output has twice as many pulses per cycle, so its frequency is 2f."],["Myth: The Zener diode lowers the current of the load.","Truth: The Zener keeps the voltage constant by taking the extra current away from the load."],["Myth: A solar cell is just a photodiode with a battery.","Truth: A solar cell has no external bias; it produces its own emf and delivers power."],["Myth: A gate with two inputs always needs two different gates to be made universal.","Truth: One kind of gate is enough. NAND alone or NOR alone can give every other gate."],["Myth: A semiconductor behaves like a metal when it is heated.","Truth: Heating a semiconductor raises the number of carriers, so its resistance falls. A metal\u2019s resistance rises."]]},extra:[]}})()})();
